LIMITER_PY = """
import asyncio
import time

class AsyncRateLimiter:
    def __init__(self, rate: int, per: float):
        self.rate = rate
        self.per = per
        self.tokens = float(rate)
        self.last_update = time.monotonic()
        self.lock = asyncio.Lock()

    async def acquire(self) -> bool:
        async with self.lock:
            now = time.monotonic()
            elapsed = now - self.last_update
            self.last_update = now
            self.tokens = min(float(self.rate), self.tokens + elapsed * (self.rate / self.per))
            if self.tokens >= 1.0:
                self.tokens -= 1.0
                return True
            return False
"""

ROUTER_PY = """
class Router:
    def __init__(self):
        self.routes = {}

    def register(self, path: str, handler):
        self.routes[path] = handler

    async def route(self, path: str, request: dict) -> dict:
        visited = list(request.get("visited", []))
        if path in visited:
            return {
                "status": "error",
                "message": f"Circular routing detected: {path} already visited in path {visited}"
            }
        visited.append(path)
        new_request = {**request, "visited": visited}
        if path not in self.routes:
            return {"status": "error", "message": f"Route {path} not found"}
        handler = self.routes[path]
        return await handler(new_request)
"""

APP_PY = """
import asyncio
import json
import sys
from auth import TokenAuth
from limiter import AsyncRateLimiter
from router import Router

class Microservice:
    def __init__(self):
        self.auth = TokenAuth(["secret-token-123", "user-token-abc"])
        self.limiter = AsyncRateLimiter(rate=3, per=1.0)
        self.router = Router()
        self._setup_routes()

    def _setup_routes(self):
        self.router.register("service_a", self.handle_service_a)
        self.router.register("service_b", self.handle_service_b)
        self.router.register("service_c", self.handle_service_c)
        self.router.register("circular_1", self.handle_circular_1)
        self.router.register("circular_2", self.handle_circular_2)

    async def handle_service_a(self, request):
        return await self.router.route("service_b", request)

    async def handle_service_b(self, request):
        return await self.router.route("service_c", request)

    async def handle_service_c(self, request):
        return {"status": "success", "data": "Hello from Service C", "visited": request.get("visited")}

    async def handle_circular_1(self, request):
        return await self.router.route("circular_2", request)

    async def handle_circular_2(self, request):
        return await self.router.route("circular_1", request)

    async def handle_request(self, request: dict) -> dict:
        token = request.get("token")
        if not await self.auth.authenticate(token):
            return {"status": "error", "message": "Unauthorized"}

        if not await self.limiter.acquire():
            return {"status": "error", "message": "Rate limit exceeded"}

        path = request.get("path")
        return await self.router.route(path, request)

async def run_tests():
    service = Microservice()
    results = []

    # Test 1: Successful Routing (A -> B -> C)
    try:
        req = {"token": "secret-token-123", "path": "service_a"}
        res = await service.handle_request(req)
        passed = (res.get("status") == "success" and 
                  res.get("visited") == ["service_a", "service_b", "service_c"])
        results.append({
            "test": "successful_routing",
            "passed": passed,
            "output": res
        })
    except Exception as e:
        results.append({"test": "successful_routing", "passed": False, "error": str(e)})

    # Test 2: Unauthorized Access
    try:
        req = {"token": "wrong-token", "path": "service_a"}
        res = await service.handle_request(req)
        passed = (res.get("status") == "error" and res.get("message") == "Unauthorized")
        results.append({
            "test": "unauthorized_access",
            "passed": passed,
            "output": res
        })
    except Exception as e:
        results.append({"test": "unauthorized_access", "passed": False, "error": str(e)})

    # Test 3: Circular Routing Detection
    try:
        req = {"token": "secret-token-123", "path": "circular_1"}
        res = await service.handle_request(req)
        passed = (res.get("status") == "error" and "Circular routing detected" in res.get("message", ""))
        results.append({
            "test": "circular_routing_detection",
            "passed": passed,
            "output": res
        })
    except Exception as e:
        results.append({"test": "circular_routing_detection", "passed": False, "error": str(e)})

    # Test 4: Rate Limiting
    try:
        # Wait 1.1 seconds to ensure rate limiter tokens are fully replenished to 3
        await asyncio.sleep(1.1)
        reqs = [{"token": "secret-token-123", "path": "service_c"} for _ in range(5)]
        responses = []
        for r in reqs:
            responses.append(await service.handle_request(r))

        success_count = sum(1 for res in responses if res.get("status") == "success")
        limited_count = sum(1 for res in responses if res.get("status") == "error" and res.get("message") == "Rate limit exceeded")

        passed = (success_count == 3 and limited_count == 2)
        results.append({
            "test": "rate_limiting",
            "passed": passed,
            "output": {
                "success_count": success_count,
                "limited_count": limited_count,
                "responses": responses
            }
        })
    except Exception as e:
        results.append({"test": "rate_limiting", "passed": False, "error": str(e)})

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    if sys.platform == "win32":
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())
    asyncio.run(run_tests())
"""

def main():
    # Create workspace directory
    os.makedirs(WORKSPACE_DIR, exist_ok=True)

    # Write files to workspace
    files = {
        "auth.py": AUTH_PY,
        "limiter.py": LIMITER_PY,
        "router.py": ROUTER_PY,
        "app.py": APP_PY
    }

    for filename, content in files.items():
        filepath = os.path.join(WORKSPACE_DIR, filename)
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content.strip() + "\n")

    # Execute app.py inside the workspace directory
    result = subprocess.run(
        [sys.executable, "app.py"],
        cwd=WORKSPACE_DIR,
        capture_output=True,
        text=True
    )

    if result.returncode != 0:
        # If execution failed, output the error in a JSON format
        error_output = [
            {
                "test": "execution",
                "passed": False,
                "error": result.stderr or result.stdout
            }
        ]
        print(json.dumps(error_output, indent=2))
        sys.exit(result.returncode)

    # Parse and print the strict JSON array of test results from app.py
    try:
        test_results = json.loads(result.stdout)
        print(json.dumps(test_results, indent=2))
    except json.JSONDecodeError:
        # Fallback if stdout is not valid JSON
        fallback_output = [
            {
                "test": "parsing",
                "passed": False,
                "error": f"Failed to parse JSON. Raw output: {result.stdout}"
            }
        ]
        print(json.dumps(fallback_output, indent=2))

if __name__ == "__main__":
    main()

